import PropTypes from 'prop-types';
import ISVDetails from './isv-details';

function IsvVendorOrderDetails(partnerId, orderSummary, local) {
  console.debug('PartnerId: ', partnerId, 'OrderDetails: ', orderSummary, 'Local: ', local);
  return new ISVDetails(orderSummary, local);
}

IsvVendorOrderDetails.propTypes = {
  partnerId: PropTypes.string.isRequired,
  orderDetails: PropTypes.object,
  local: PropTypes.func.isRequired,
};

export default IsvVendorOrderDetails;
