import PropTypes from 'prop-types';

function ISVDetails(orderSummary, local) {
  return {
    getRows() {
      return [
        {
          label: local('review-order.customer_info.customer_order'),
          value: orderSummary?.orderDetails.vendorOrderId ?? '-',
        },
      ];
    },
  };
}

ISVDetails.propTypes = {
  orderDetails: PropTypes.object.isRequired,
  local: PropTypes.func.isRequired,
};

export default ISVDetails;
